const revision = '4249661388e5d3f92a85186213da140a6481490f';
const sha = path => crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex');
const binarySha256 = sha(binary);
const git = (...args) => cp.execFileSync('git', ['-C', repo + '/test262', ...args], { encoding: 'utf8' }).trim();
assert.equal(git('rev-parse', 'HEAD'), revision);
assert.equal(git('status', '--porcelain'), '');
const subtrees = [
  ['test/built-ins/RegExp', 1879],
  ['test/language/literals/regexp', 238],
  ...Object.entries({match:51,matchAll:25,replace:55,replaceAll:45,search:43,split:120})
    .map(([name, count]) => ['test/built-ins/String/prototype/' + name, count]),
];
const env = { ...process.env, HOME_RUN_MAX_MB:'3072',
  HOME_RUN_LOCK:'/Users/glennmichaeltorregosa/.cache/home-run.lock', HOME_RUN_LABEL:'codex-989-full-qualification' };
const summary = { corpusRevision: revision, binarySha256, complete: false, subtrees: [], total: 0 };
for (const [subtree, expected] of subtrees) {
  const files = [];
  function inventory(dir, prefix = '') {
    for (const d of fs.readdirSync(dir, { withFileTypes:true })) {
      if (d.isDirectory()) inventory(dir + '/' + d.name, prefix + d.name + '/');
      else if (d.isFile() && d.name.endsWith('.js') && !d.name.endsWith('_FIXTURE.js'))
        files.push({path:prefix + d.name, sha256:sha(dir + '/' + d.name)});
    }
  }
  inventory(repo + '/test262/' + subtree);
  assert.equal(files.length, expected);
  const prefix = subtree.replaceAll('/', '-');
  const result = { subtree, files, expected, p:0, n:0, receipts:[] };
  for (let start = 0; start < expected; start += 25) {
    const count = Math.min(25, expected - start);
    const name = prefix + '-' + start;
    const log = root + '/' + name + '.log';
    const fd = fs.openSync(log, 'wx');
    let run;
    try {
      run = cp.spawnSync('perl', [guard, '900', binary, '--worker', subtree, String(start), String(count)],
        { cwd:repo, env, stdio:['ignore',fd,fd] });
    } finally { fs.closeSync(fd); }
    const raw = fs.readFileSync(log, 'utf8');
    const lines = raw.split(/\r?\n/).filter(l => /^\d+:[pnsPRFO]$/.test(l) || /^(MORE|DONE)$/.test(l));
    const receipt = {subtree,start,count,status:run.status,signal:run.signal,error:run.error?.message,
      binarySha256,corpusRevision:revision,log,protocol:lines,complete:false};
    const valid = run.status === 0 && !run.signal && lines.length === count + 1 &&
      lines[count] === (start + count === expected ? 'DONE' : 'MORE') &&
      lines.slice(0,count).every((l,i) => new RegExp('^' + (start+i) + ':[pn]$').test(l));
    receipt.complete = valid;
    fs.writeFileSync(root + '/' + name + '.json', JSON.stringify(receipt,null,2)+'\n', {flag:'wx'});
    assert.ok(valid, 'Incomplete or failed range: ' + name + '; inspect retained log');
