const baseline = load(prior + '/regexp-resource-qualification.json');
add('prior/regexp-resource-qualification.json', prior + '/regexp-resource-qualification.json');
for (const name of baseline.receipts) {
  if (load(prior + '/' + name).side === 'after') add('prior/' + name, prior + '/' + name);
