allocation-probe.zig.text:
const std = @import("std");
const regex = @import("regex");

// Diagnostic only: retained arena capacity, not a conformance/performance gate.
pub fn main() !void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    std.debug.print("iteration\tbefore\tcompiled\tmatched\tnfa_states\n", .{});
    for (0..16) |i| {
        const before = arena.queryCapacity();
        const re = try allocator.create(regex.Regex);
        re.* = try regex.Regex.compileWithFlags(allocator, "\\S+", .{ .ecmascript = true });
        const compiled = arena.queryCapacity();
        var matcher = re.matcher();
        // Retain exactly as the interpreter's per-program matcher cache does.
        const result = try matcher.find("a");
        if (result == null) return error.UnexpectedNoMatch;
        std.debug.print("{d}\t{d}\t{d}\t{d}\t{d}\n", .{
            i, before, compiled, arena.queryCapacity(), re.nfa.states.items.len,
        });
    }
}

