checks.push(second.source === "a" && second.flags === "g" && second.exec("aa").index === 1);
checks.push(fresh().exec("a")[0] === "a");
try { first.compile("[", "g"); checks.push(false); } catch (e) { checks.push(e instanceof SyntaxError); }
